// Discovers the PNG icons generated by Expo and reports unsupported iOS icon folders.
import { extname, join } from "node:path";
import {
  type ExportedConfig,
  IOSConfig,
  WarningAggregator,
} from "expo/config-plugins";
import type { IconTarget } from "./targets";

export function findIosIconTargets(
  config: ExportedConfig,
  projectRoot: string
): IconTarget[] {
  const icons = config.ios?.icon;
  const icon = typeof icons === "string" ? icons : config.icon;
  const hasAppearanceIcons =
    typeof icons === "object" &&
    Boolean(icons.light || icons.dark || icons.tinted);
  if (!hasAppearanceIcons && icon && extname(icon) === ".icon") {
    WarningAggregator.addWarningIOS(
      "ios.icon",
      `expo-icon-overlays: ${icon} uses an unsupported .icon folder. No iOS overlays were applied. Use PNG icons to apply overlays.`
    );
    return [];
  }
  const directory = join(
    projectRoot,
    "ios",
    IOSConfig.XcodeUtils.getProjectName(projectRoot),
    "Images.xcassets",
    "AppIcon.appiconset"
  );
  const targets: IconTarget[] = [
    { path: join(directory, "App-Icon-1024x1024@1x.png"), surface: "square" },
  ];
  if (typeof icons === "object") {
    if (icons.dark) {
      targets.push({
        path: join(directory, "App-Icon-dark-1024x1024@1x.png"),
        surface: "square",
      });
    }
    if (icons.tinted) {
      targets.push({
        path: join(directory, "App-Icon-tinted-1024x1024@1x.png"),
        surface: "square-tinted",
      });
    }
  }
  return targets;
}
